const clean=x=>String(x||'').replace(/\s+/g,' ').trim();
async function page(url){const r=await fetch(url,{credentials:'omit',cache:'no-store'});if(!r.ok)throw new Error('Lyft public page HTTP '+r.status);if(new URL(r.url).origin!=='https://www.lyft.com')throw new Error('Unexpected Lyft redirect');return new DOMParser().parseFromString(await r.text(),'text/html');}
window.ox.install(({action})=>{
action('searchCities',{async invoke({query}){const d=await page('/rider/cities');const seen=new Set();const entries=[...d.querySelectorAll('a[href]')].map(a=>({name:clean(a.textContent),url:new URL(a.getAttribute('href'),'https://www.lyft.com').href})).filter(x=>x.name&&x.url.startsWith('https://www.lyft.com/rider/cities/')&&!seen.has(x.url)&&seen.add(x.url));if(!entries.length)throw new Error('Lyft city directory unavailable or changed');const items=entries.filter(x=>(x.name+' '+x.url).toLowerCase().includes(query.trim().toLowerCase()));if(items.length>1000)throw new Error('Too many matches; use a more specific city name');return {items,nextCursor:null};}});
action('getCity',{async invoke({url}){const u=new URL(url);if(u.origin!=='https://www.lyft.com'||u.username||u.password||!/^\/rider\/cities\/[a-z0-9/-]+$/.test(u.pathname)||u.search||u.hash)throw new Error('Use a city URL returned by Search supported cities');const d=await page(u.href);const information=[...new Set([...d.querySelectorAll('main h1,main h2,main h3,main p')].map(x=>clean(x.textContent)).filter(Boolean))];if(!information.length)throw new Error('Lyft city content unavailable or changed');return {url:u.href,title:clean(d.title),information};}});
});